// Hidden verifier. The agent never sees this file: it is written into the
// workspace only after the agent has finished.
import { spawn } from 'node:child_process';

const PORT = 39117;
const base = `http://127.0.0.1:${PORT}`;
const server = spawn('node', ['server.js'], {
  env: { ...process.env, PORT: String(PORT) },
  stdio: ['ignore', 'pipe', 'pipe'],
});
let serverOutput = '';
server.stdout.on('data', d => { serverOutput += d; });
server.stderr.on('data', d => { serverOutput += d; });

const fail = (message) => {
  server.kill('SIGKILL');
  console.error(`FAIL: ${message}\n--- server output ---\n${serverOutput.slice(0, 2000)}`);
  process.exit(1);
};

const get = async (path, options) => {
  const response = await fetch(base + path, options);
  let body = null;
  try { body = await response.json(); } catch { body = null; }
  return { status: response.status, body };
};

// Wait for the server to accept connections rather than assuming a delay.
const ready = async () => {
  for (let i = 0; i < 100; i++) {
    try { await fetch(base + '/health'); return true; } catch { await new Promise(r => setTimeout(r, 100)); }
  }
  return false;
};

try {
  if (!await ready()) fail('server never accepted a connection on /health');

  let r = await get('/health');
  if (r.status !== 200) fail(`GET /health returned ${r.status}, expected 200`);
  if (!r.body || r.body.status !== 'ok') fail(`GET /health body was ${JSON.stringify(r.body)}`);

  r = await get('/todos');
  if (r.status !== 200) fail(`GET /todos returned ${r.status}`);
  if (!Array.isArray(r.body) || r.body.length !== 0) fail(`GET /todos body was ${JSON.stringify(r.body)}`);

  r = await get('/todos', {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ title: 'write tests' }),
  });
  if (r.status !== 201) fail(`POST /todos returned ${r.status}, expected 201`);
  if (!r.body || r.body.title !== 'write tests' || r.body.done !== false || typeof r.body.id !== 'number') {
    fail(`POST /todos body was ${JSON.stringify(r.body)}`);
  }
  const id = r.body.id;

  r = await get('/todos');
  if (r.body.length !== 1) fail(`after one POST, GET /todos had ${r.body.length} items`);

  r = await get(`/todos/${id}`);
  if (r.status !== 200 || r.body.id !== id) fail(`GET /todos/${id} returned ${r.status} ${JSON.stringify(r.body)}`);

  r = await get('/todos/999999');
  if (r.status !== 404) fail(`GET /todos/999999 returned ${r.status}, expected 404`);
  if (!r.body || r.body.error !== 'not found') fail(`404 body was ${JSON.stringify(r.body)}`);

  r = await get(`/todos/${id}/done`, { method: 'POST' });
  if (r.status !== 200) fail(`POST /todos/${id}/done returned ${r.status}`);
  if (r.body.done !== true) fail(`after done, body was ${JSON.stringify(r.body)}`);

  r = await get(`/todos/${id}`);
  if (r.body.done !== true) fail('done did not persist');

  r = await get('/todos/999999/done', { method: 'POST' });
  if (r.status !== 404) fail(`POST /todos/999999/done returned ${r.status}, expected 404`);
  if (!r.body || r.body.error !== 'not found') fail(`done-404 body was ${JSON.stringify(r.body)}`);

  // A second todo must get a different id, and both must be listed.
  r = await get('/todos', {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ title: 'second' }),
  });
  if (r.status !== 201) fail(`second POST /todos returned ${r.status}`);
  if (r.body.id === id) fail('ids are not unique');
  if (r.body.done !== false) fail('a new todo was not created undone');
  const listed = await get('/todos');
  if (listed.body.length !== 2) fail(`after two POSTs, GET /todos had ${listed.body.length}`);
  // Marking one done must not mark the other.
  if (listed.body.filter(t => t.done).length !== 1) fail('done leaked across todos');

  server.kill('SIGKILL');
  console.log('OK');
  process.exit(0);
} catch (error) {
  fail(`verifier threw: ${error && error.stack ? error.stack : error}`);
}

